package app.multimin.ui;
import javax.swing.*;
import java.awt.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.Properties;
import javax.swing.border.EmptyBorder;
import java.awt.Font;
import java.awt.Color;
public final class LegalConsent {
 private static Palette THEME=new Palette();
 private static final String VERSION="2026-11-05-updates";
 private static String read(String name){try(var in=LegalConsent.class.getResourceAsStream("/legal/"+name)){if(in==null)return "Document unavailable. Obtain the complete release before using capture.";return new String(in.readAllBytes(),StandardCharsets.UTF_8);}catch(Exception e){return "Document could not be read.";}}
 private static Color BG=new Color(24,27,33), PANEL=new Color(35,39,48), TEXT=new Color(232,235,240), MUTED=new Color(150,157,169), ACCENT=new Color(103,153,255);
 public static void setPalette(Palette palette){THEME=palette;BG=palette.background;PANEL=palette.controlSurface();TEXT=palette.text;MUTED=palette.muted;ACCENT=palette.accent;}
 private static JTabbedPane documents(){JTabbedPane tabs=new JTabbedPane();tabs.setFont(new Font(Font.DIALOG,Font.BOLD,13));tabs.setBackground(PANEL);tabs.setForeground(TEXT);for(String name:new String[]{"TERMS.md","PRIVACY.md"}){JTextArea text=new JTextArea(read(name),24,76);text.setEditable(false);text.setLineWrap(true);text.setWrapStyleWord(true);text.setCaretPosition(0);text.setFont(new Font(Font.DIALOG,Font.PLAIN,13));text.setBackground(PANEL);text.setForeground(TEXT);text.setSelectionColor(ACCENT);text.setSelectedTextColor(Color.WHITE);text.setBorder(new EmptyBorder(14,16,14,16));JScrollPane scroll=new JScrollPane(text);scroll.setBorder(javax.swing.BorderFactory.createLineBorder(new Color(82,90,105)));scroll.getViewport().setBackground(PANEL);scroll.getVerticalScrollBar().setUnitIncrement(18);tabs.add(name.equals("TERMS.md")?"User agreement":"Privacy notice",scroll);}return tabs;}
 public static void showDocuments(Component parent){JOptionPane.showMessageDialog(parent,documents(),"MultiMini agreement and privacy",JOptionPane.PLAIN_MESSAGE);}
 public static boolean ensureAccepted(){if(LegalConsent.class.getResource("/legal/TERMS.md")==null || LegalConsent.class.getResource("/legal/PRIVACY.md")==null){JOptionPane.showMessageDialog(null,"Agreement documents are missing. Please obtain the complete release.");return false;}Path path=WorkspaceStore.directory().resolve("agreement.properties");Properties p=new Properties();try(var in=Files.newInputStream(path)){p.load(in);if(VERSION.equals(p.getProperty("acceptedVersion")))return true;}catch(Exception ignored){}
  JDialog dialog=new JDialog((Frame)null,"Welcome to MultiMini",true);JPanel body=new JPanel(new BorderLayout(14,14));body.setBackground(BG);body.setBorder(BorderFactory.createEmptyBorder(20,22,18,22));JLabel intro=new JLabel("<html><b>Welcome to MultiMini</b><br><span style='color:#969da9'>Review the user agreement and privacy notice before using capture or input.</span></html>");intro.setFont(new Font(Font.DIALOG,Font.PLAIN,14));intro.setForeground(TEXT);body.add(intro,BorderLayout.NORTH);body.add(documents(),BorderLayout.CENTER);JCheckBox agree=new JCheckBox("I have read and agree to the User Agreement and have read the Privacy Notice.");agree.setOpaque(false);agree.setForeground(TEXT);agree.setFont(new Font(Font.DIALOG,Font.PLAIN,12));agree.setIcon(new AccentCheckIcon(THEME));JButton accept=new ModernButton("Agree and continue",null,THEME,true),decline=new ModernButton("Decline and exit",null,THEME,false);accept.setEnabled(false);agree.addActionListener(e->accept.setEnabled(agree.isSelected()));boolean[] result={false};accept.addActionListener(e->{try{Files.createDirectories(path.getParent());Properties record=new Properties();record.setProperty("acceptedVersion",VERSION);record.setProperty("acceptedAt",java.time.Instant.now().toString());try(var out=Files.newOutputStream(path)){record.store(out,"MultiMini local agreement acceptance");}result[0]=true;dialog.dispose();}catch(Exception error){JOptionPane.showMessageDialog(dialog,"Could not save acceptance: "+error.getMessage());}});decline.addActionListener(e->dialog.dispose());JPanel bottom=new JPanel(new BorderLayout(8,12));bottom.setBackground(BG);bottom.add(agree,BorderLayout.NORTH);JPanel buttons=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));buttons.setOpaque(false);buttons.add(decline);buttons.add(accept);bottom.add(buttons,BorderLayout.SOUTH);body.add(bottom,BorderLayout.SOUTH);dialog.setContentPane(body);dialog.setMinimumSize(new Dimension(720,540));dialog.setSize(920,680);dialog.setResizable(true);dialog.setLocationRelativeTo(null);dialog.setVisible(true);return result[0];
 }
}
